def load_pairs(path, cap):
    d=json.load(open(path))
    ids=[it['name'] for it in d['items'] if it.get('subfamily')=='pair']
    pol={it['name']:it['polarity'] for it in d['items']}
    pp=cap['per_prompt']
    out={}
