        pos=[pp[L][i] for i in range(len(ids)) if pol[ids[i]]=='think']
        neg=[pp[L][i] for i in range(len(ids)) if pol[ids[i]]=='dont_think']
        out[L]=torch.stack(pos).mean(0)-torch.stack(neg).mean(0)
    return out, len(ids)
